async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  store: SessionStore,
  message: ListSessionsMessage
): Promise<void> {
  if (!store.listFor) {
    ws.send(JSON.stringify({type: 'session_list', sessions: []}));
    return;
  }

  try {
    const summaries = await store.listFor(session.userId, {
      limit: message.limit,
      before: message.before
    });

    const sessions = summaries.map(s => ({
      sessionId: s.sessionId,
      createdAt: s.createdAt instanceof Date ? s.createdAt.toISOString() : s.createdAt,
      updatedAt: s.updatedAt instanceof Date ? s.updatedAt.toISOString() : s.updatedAt,
      entryCount: s.entryCount
    }));

    ws.send(JSON.stringify({type: 'session_list', sessions}));
  } catch (error) {
    const errorMsg = error instanceof Error ? error.message : 'Unknown error';
    log.error('ws', 'listFor threw an error', {userId: session.userId, error: errorMsg});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
  }
}
